# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""Triton implementation of elementwise true division (aten::divide / true_divide).

Semantics: out[i] = float(self[bcast(i)]) / float(other[bcast(i)]) with numpy
right-aligned broadcasting.  fp16/bf16 (and integer) operands are divided in
fp32 and rounded once at the store, matching ATen's opmath behaviour.
"""

import logging

import torch
import triton
import triton.language as tl

logger = logging.getLogger("flag_gems.ops.divide")

_BLOCK_MAX = 2048
_MAX_RANK = 8
_TUNE_MIN_NUMEL = 65536
_BLOCK_CHOICES = (1024, 2048, 4096, 8192)


@triton.jit
def _divide_impl(
    a_ptr,
    b_ptr,
    o_ptr,
    numel,
    P0,
    P1,
    P2,
    P3,
    P4,
    P5,
    P6,
    A0,
    A1,
    A2,
    A3,
    A4,
    A5,
    A6,
    B0,
    B1,
    B2,
    B3,
    B4,
    B5,
    B6,
    alast,
    blast,
    R: tl.constexpr,
    BLOCK: tl.constexpr,
    USE_F64: tl.constexpr,
    SCAL_A: tl.constexpr,
    SCAL_B: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < numel

    rem = offs
    oa = tl.zeros((BLOCK,), dtype=tl.int32)
    ob = tl.zeros((BLOCK,), dtype=tl.int32)

    if R > 1:
        idx = rem // P0
        rem = rem - idx * P0
        oa += idx * A0
        ob += idx * B0
    if R > 2:
        idx = rem // P1
        rem = rem - idx * P1
        oa += idx * A1
        ob += idx * B1
    if R > 3:
        idx = rem // P2
        rem = rem - idx * P2
        oa += idx * A2
        ob += idx * B2
    if R > 4:
        idx = rem // P3
        rem = rem - idx * P3
        oa += idx * A3
        ob += idx * B3
    if R > 5:
        idx = rem // P4
        rem = rem - idx * P4
        oa += idx * A4
        ob += idx * B4
    if R > 6:
        idx = rem // P5
        rem = rem - idx * P5
        oa += idx * A5
        ob += idx * B5
    if R > 7:
        idx = rem // P6
        rem = rem - idx * P6
        oa += idx * A6
        ob += idx * B6

    oa += rem * alast
    ob += rem * blast

    if SCAL_A:
        a = tl.load(a_ptr)
    else:
        a = tl.load(a_ptr + oa, mask=mask, other=0.0)
    if SCAL_B:
        b = tl.load(b_ptr)
    else:
        b = tl.load(b_ptr + ob, mask=mask, other=1.0)
    if USE_F64:
        r = a.to(tl.float64) / b.to(tl.float64)
    else:
        r = a.to(tl.float32) / b.to(tl.float32)
    tl.store(o_ptr + offs, r, mask=mask)


