@triton.jit
def _mul_neg_kernel(p_ptr, q_ptr, o_ptr, numel, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < numel
    p = tl.load(p_ptr + offs, mask=mask, other=0.0)
    q = tl.load(q_ptr + offs, mask=mask, other=0.0)
    tl.store(o_ptr + offs, -(p.to(tl.float32) * q.to(tl.float32)), mask=mask)


@triton.jit
def _sum_dim_kernel(x_ptr, o_ptr, total, red, inner, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    idx = pid * BLOCK + tl.arange(0, BLOCK)
    mask = idx < total
    outer = idx // inner
    pos = idx - outer * inner
    base = outer * (red * inner) + pos
    acc = tl.zeros((BLOCK,), dtype=tl.float32)
    for r in range(0, red):
        acc += tl.load(x_ptr + base + r * inner, mask=mask, other=0.0).to(tl.float32)
    tl.store(o_ptr + idx, acc, mask=mask)


def _pick_block(numel):
    if numel >= _BLOCK_MAX:
        return _BLOCK_MAX
    block = 16
    while block < numel:
        block <<= 1
    return block


def _size_class(numel):
    # Triton specializes integer args equal to 1, so classes start at 2.
    if numel < (1 << 22):
        return 2
    if numel < (1 << 26):
        return 4
    return 8


def _align_strides(x, nd):
    """Effective strides of ``x`` right-aligned to an ``nd``-dim output shape."""
    strides = [0] * nd
    xs = x.shape
    xst = x.stride()
    off = nd - len(xs)
    for i in range(len(xs)):
        if xs[i] != 1:
            strides[off + i] = xst[i]
    return strides


def _collapse(shape, sa, sb):
    """Merge adjacent dims that stay affine for both operands."""
    shape = list(shape)
    sa = list(sa)
    sb = list(sb)
    i = len(shape) - 1
    while i > 0:
        so = shape[i - 1]
        si = shape[i]
        if si == 1:
            del shape[i]
            del sa[i]
            del sb[i]
        elif so == 1:
            shape[i - 1] = si
            sa[i - 1] = sa[i]
            sb[i - 1] = sb[i]
            del shape[i]
            del sa[i]
            del sb[i]
        elif sa[i - 1] == sa[i] * si and sb[i - 1] == sb[i] * si:
            shape[i - 1] = so * si
            sa[i - 1] = sa[i]
            sb[i - 1] = sb[i]
            del shape[i]
            del sa[i]
            del sb[i]
        i -= 1
    return shape, sa, sb


def _launch(a, b, out):
    numel = out.numel()
    if numel == 0:
        return
    nd = out.dim()
    sa = _align_strides(a, nd)
    sb = _align_strides(b, nd)
    if nd == 0:
        shape = [1]
        sa = [0]
        sb = [0]
    else:
        shape = list(out.shape)

    shape, sa, sb = _collapse(shape, sa, sb)
    rank = len(shape)
    if rank > _MAX_RANK:
        # Extremely high rank (never hit in practice): slice along dim 0.
        for i in range(out.shape[0]):
            oi = out.select(0, i)
            ai = a.select(0, i) if (a.dim() == nd and a.shape[0] == out.shape[0]) else a
            bi = b.select(0, i) if (b.dim() == nd and b.shape[0] == out.shape[0]) else b
            _launch(ai, bi, oi)
        return

    # suffix products: P[d] = prod(shape[d+1:])
    ps = [1] * rank
    for d in range(rank - 2, -1, -1):
        ps[d] = ps[d + 1] * shape[d + 1]

    pargs = (ps + [0] * 7)[:7]
    aargs = (sa[:7] + [0] * 7)[:7]
    bargs = (sb[:7] + [0] * 7)[:7]

    scal_a = a.numel() == 1
    scal_b = b.numel() == 1
    use_f64 = out.dtype == torch.float64

    if numel >= _TUNE_MIN_NUMEL:
        size_class = _size_class(numel)
        grid = lambda meta: (triton.cdiv(numel, meta["BLOCK"]),)
        _divide_kernel_tuned[grid](
            a,
            b,
            out,
            numel,
            size_class,
            *pargs,
            *aargs,
            *bargs,
            sa[rank - 1],
            sb[rank - 1],
            R=rank,
            USE_F64=use_f64,
            SCAL_A=scal_a,
            SCAL_B=scal_b,
        )
    else:
        block = _pick_block(numel)
        grid = (triton.cdiv(numel, block),)
        _divide_kernel[grid](
            a,
            b,
            out,
            numel,
            *pargs,
            *aargs,
            *bargs,
            sa[rank - 1],
            sb[rank - 1],
            R=rank,
            BLOCK=block,
            USE_F64=use_f64,
            SCAL_A=scal_a,
            SCAL_B=scal_b,
        )


def _divide(a, b):
    out_shape = torch.broadcast_shapes(a.shape, b.shape)  # allow-torch-compute
    dtype = torch.result_type(a, b)
    if not dtype.is_floating_point:
        # integer / bool inputs: true division promotes to the default float
        dtype = torch.get_default_dtype()
    out = torch.empty(out_shape, dtype=dtype, device=a.device)
    _launch(a, b, out)
    return out


def _mul_neg(p, q, numel, dtype, device):
    out = torch.empty(numel, dtype=dtype, device=device)
    if numel > 0:
        block = _pick_block(numel)
        grid = (triton.cdiv(numel, block),)
        _mul_neg_kernel[grid](p, q, out, numel, BLOCK=block)
    return out


def _sum_to(t, shape):
    """Reduce a broadcast-shaped tensor back to ``shape`` with device kernels."""
    target = tuple(shape)
    if tuple(t.shape) == target:
        return t
    cur = t
    cur_shape = list(t.shape)
    lead = len(cur_shape) - len(target)
    red_dims = list(range(lead))
    for i, s in enumerate(target):
        d = lead + i
        if s == 1 and cur_shape[d] != 1:
            red_dims.append(d)
    for d in sorted(red_dims, reverse=True):
        outer = 1
        for s in cur_shape[:d]:
            outer *= s
        red = cur_shape[d]
        inner = 1
        for s in cur_shape[d + 1 :]:
            inner *= s
        total = outer * inner
        out = torch.empty(total, dtype=cur.dtype, device=cur.device)
        if total > 0:
            block = _pick_block(total)
            grid = (triton.cdiv(total, block),)
            _sum_dim_kernel[grid](cur, out, total, red, inner, BLOCK=block)
        cur_shape[d] = 1
        cur = out.view(cur_shape)
    return cur.view(target)


class _DivideFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, a, b):
        out = _divide(a, b)
        ctx.save_for_backward(a, b, out)
        return out

    @staticmethod
    def backward(ctx, grad):
        a, b, out = ctx.saved_tensors
        need_a, need_b = ctx.needs_input_grad[0], ctx.needs_input_grad[1]
        grad_a = None
        grad_b = None
        if need_a or need_b:
            u = _divide(grad, b)
            if need_a:
                grad_a = _sum_to(u, a.shape)
            if need_b:
                neg_u_out = _mul_neg(u, out, out.numel(), out.dtype, out.device)
                grad_b = _sum_to(neg_u_out.view(out.shape), b.shape)
        return grad_a, grad_b


def run(self, other):
    logger.debug("GEMS DIVIDE")
    a = self
    b = other
    if a.requires_grad or b.requires_grad:
        return _DivideFunction.apply(a, b)
    return _divide(a, b)


def divide(*args, **kwargs):
    logger.debug("GEMS_ASCEND DIVIDE")
    return run(*args, **kwargs)
